// Pick leads worth searching, and precompute everything the HTTP nodes need so
// they stay dumb pipes.
const MAX_PER_RUN = 100;

// FIXTURE RUN (Task 4): restrict the run to the 15 known-answer leads on the
// 'Email Finder Test Set' tab. Empty the array to run against the whole pool.
const RUN_FIXTURE_ONLY = false;   // true re-tests only the 15 known answers
const FIXTURE_IDS = [
  'ACoAAAGlU_cBfORam-XoWETz1LypgALJIE3qCKw', // Ryan Kaup - Apache Junction AZ - found
  'ACoAABBUCrgBprZD15mTqHQC6MQNavHIVWljZgI', // Jon Rickard - College Place WA - found
  'ACoAAAMbmnIBhvmssIDVCw1LSb9hiqI7v2rltVY', // Gustavo Gonzalez - Eastvale CA - found
  'ACoAAA7TUTgBPVVT-9yHu1EQLwNVPf7jT7v6r3I', // Micah Scoggan - Goddard KS - found
  'ACoAABafkkAB2DrfVczb8wM9pj79_ob_kA7UjKA', // Kayla Charters - Menifee CA - found
  'ACoAAAUwVh0BetEvNrtGsCKIN25smgj6LXo5mpo', // Stephen Lachky - Parkville MO - found
  'ACoAAAOIBskB6cpDfxkOdLD7tleLT--mcmli6d0', // RJ Lott - Pullman WA - found (first.last)
  'ACoAAA7FjfYBfkwdrfr5Ny4iPy1qvZZ-mKRsw0I', // Brett Angell - Rogers MN - found
  'ACoAADLf1YkBZUgZuuR0UHGVtx4n-4FE880KKk4', // Jerod Potts - Sachse TX - found
  'ACoAAAKdpBYBFTN3njkPVAqs_1iqpU4_74_x44A', // Benjamin Boike - West St. Paul MN - found
  'ACoAAAJerOcBM-Y60SniEQRuOmOzfF-HxxIpZU4', // Natali Fani-Gonzalez - Montgomery County MD - found
  'ACoAAAofS2ABpN5mnLxDKmWyf5ksMj9GTDnoHD0', // Suzanne Boyles - Buckeye AZ - NOT_FOUND expected
  'ACoAABTTXVYBx2--ANc0RElaVov7G8zkytgWCWs', // Patti Garibay - Lancaster CA - NOT_FOUND expected
  'ACoAAAK5ttcBjVmyMITBJGyVWZDK713VSUnUpqI', // Richard Wilkie - Casa Grande AZ - NOT_FOUND expected
  'ACoAAAkj484BFSuNOrxvBNJ4C4hGFPMJbkESGBQ'  // Marsellas Williams - Powder Springs GA - STALE, no address should be written
];
const ONLY_PROVIDER_IDS = RUN_FIXTURE_ONLY ? FIXTURE_IDS : [];
const ONLY_SLICE = '';          // e.g. 'municipal' — blank means every slice
const RETRY_SEARCH_ERRORS = true;

// A fixture run re-tests the same leads over and over, so it ignores the
// already-searched and already-has-an-email guards. Pool runs keep both.
const FIXTURE_MODE = ONLY_PROVIDER_IDS.length > 0;

const ne = (v) => v !== undefined && v !== null && String(v).trim() !== '';

// A company_name made only of job words is a LinkedIn headline fragment, not an
// employer. 'Biotech Entrepreneur' and 'Food Startup' sit in the pool as orgs.
const ROLE_WORDS = new Set(['director','directors','leader','leaders','leadership','manager','management','executive','officer','president','founder','cofounder','ceo','coo','cfo','cto','chair','chairman','board','consultant','consulting','strategist','specialist','coordinator','administrator','administration','program','programs','development','fundraising','fundraiser','grant','grants','writer','writing','nonprofit','profit','volunteer','entrepreneur','inventor','professional','freelance','independent','self','employed','retired','advisor','adviser','principal','owner','partner','associate','analyst','engineer','designer','marketing','sales','operations','recruiter','student','intern','philanthropy','philanthropist','relations','affairs','outreach','engagement','strategy','strategic','startup','biotech','tech','coach','mentor','speaker','author','investor','advocate']);
const STOPWORDS = new Set(['the','of','for','and','a','an','at','in','on','to','inc','llc','ltd','corp','corporation','co','company','group','holdings','plc','org','organization','organisation']);
const PLACEHOLDER_NAMES = new Set(['john doe','jane doe','john smith','jane smith','alice smith','alice johnson','alice','margaret smith','test user']);

function orgTokens(name) {
  const toks = String(name || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);
  const meaningful = toks.filter(t => !STOPWORDS.has(t));
  return { toks, meaningful, distinctive: meaningful.filter(t => !ROLE_WORDS.has(t)) };
}

// Lead Pool stores credentials in the name: 'RJ Lott, CGFM, MPA, AICP, CPM, PHR'.
// Searching the credentials finds nothing, so cut at the first comma.
function cleanName(n) {
  let s = String(n || '').split(',')[0];
  s = s.replace(/\([^)]*\)/g, ' ');
  s = s.replace(/\b(dr|rev|minister|bishop|mr|mrs|ms|prof|sr|jr)\.?\s+/gi, ' ');
  s = s.replace(/[^A-Za-zÀ-ɏ\s'\-]/g, ' ').replace(/\s+/g, ' ').trim();
  return s;
}

const skipped = {};
const bump = (k) => { skipped[k] = (skipped[k] || 0) + 1; };
const out = [];

for (const item of $input.all()) {
  const r = item.json;

  if (!ne(r.provider_id)) { bump('no_provider_id'); continue; }
  if (ONLY_PROVIDER_IDS.length && !ONLY_PROVIDER_IDS.includes(String(r.provider_id).trim())) { bump('not_in_fixture'); continue; }

  const findStatus = String(r.email_find_status || '').trim().toLowerCase();
  if (findStatus && !FIXTURE_MODE) {
    // not_found stays not_found. Only transient failures are retried.
    const retryable = findStatus === 'search_error' || findStatus === 'domain_not_found';
    if (!(RETRY_SEARCH_ERRORS && retryable)) { bump('already_searched_' + findStatus); continue; }
  }

  if (ne(r.email_sent_at) && !FIXTURE_MODE) { bump('already_emailed'); continue; }
  const sendStatus = String(r.email_send_status || '').toLowerCase();
  if (sendStatus === 'unsubscribed' || sendStatus === 'bounced') { bump('suppressed'); continue; }

  // Search when there is no address, or when the one we hold was invented.
  const src = String(r.email_source || '').toLowerCase();
  const hasRealEmail = ne(r.email) && !/pattern|guess|unevidenced/.test(src);
  if (hasRealEmail && !FIXTURE_MODE) { bump('already_has_observed_email'); continue; }

  if (ONLY_SLICE && String(r.slice || '').toLowerCase() !== ONLY_SLICE.toLowerCase()) { bump('wrong_slice'); continue; }

  const org = orgTokens(r.company_name);
  if (!org.toks.length) { bump('no_company_name'); continue; }
  if (!org.distinctive.length) { bump('company_is_job_title'); continue; }

  const person = cleanName(r.name);
  const parts = person.split(' ').filter(Boolean);
  if (parts.length < 2) { bump('name_not_a_person'); continue; }
  if (PLACEHOLDER_NAMES.has(person.toLowerCase())) { bump('placeholder_name'); continue; }

  // Reuse an already-evidenced domain and skip step 1 entirely. A domain from
  // v1 is NOT evidence — v1 built domains out of company_name — so it only
  // counts when company_domain_source says something actually found it.
  const domSrc = String(r.company_domain_source || '').trim();
  const trustedDomain = (ne(r.company_domain) && domSrc && !/pattern|guess|unevidenced/i.test(domSrc))
    ? String(r.company_domain).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '')
    : '';

  out.push({ json: Object.assign({}, r, {
    _person: person,
    _surname: parts[parts.length - 1],
    _org: String(r.company_name).trim(),
    _org_tokens: org.distinctive,
    _domain: trustedDomain,
    _domain_source: trustedDomain ? ('reused:' + domSrc) : ''
  })});
}

// Spread the run across organisations instead of taking leads in sheet order.
// We only need 2-3 successes at an org to learn its format; the rest of its
// people get filled from the pattern. Without this cap, one org with 40 leads
// eats the whole run and teaches us nothing after the third.
const MAX_PER_ORG = 3;
const perOrg = new Map();
const spread = [];
for (const o of out) {
  const key = String(o.json._domain || o.json._org || '').toLowerCase();
  const n = perOrg.get(key) || 0;
  if (n >= MAX_PER_ORG) { bump('org_quota_reached'); continue; }
  perOrg.set(key, n + 1);
  spread.push(o);
}

console.log('Finder queue: ' + out.length + ' eligible, ' + spread.length + ' after per-org cap, searching ' + Math.min(spread.length, MAX_PER_RUN));
console.log('Organisations covered this run: ' + perOrg.size);
console.log('Already have a trusted domain: ' + out.filter(o => o.json._domain).length);
console.log('Skipped: ' + JSON.stringify(skipped));

return spread.slice(0, MAX_PER_RUN);

// Decide which host is the organisation's own website. Everything downstream
// depends on this being right, so be conservative: no confident pick means
// domain_not_found, which is retryable, rather than a guess.
const lead = $('Loop Over Leads').item.json;
const res = $json || {};
const orgTok = Array.isArray(lead._org_tokens) ? lead._org_tokens : [];

const web = (res.data && Array.isArray(res.data.web)) ? res.data.web
  : (Array.isArray(res.data) ? res.data : []);

if (res.error || !web.length) {
  return { json: Object.assign({}, lead, { _domain: '', _domain_source: '', _domain_fail: res.error ? ('search_error: ' + (function(e){ try { return typeof e === 'string' ? e : JSON.stringify(e); } catch (x) { return 'unreadable'; } })(res.error).slice(0, 300)) : 'no results' }) };
}

// Hosts that are never an organisation's own site.
const NEVER = /(linkedin|facebook|twitter|x\.com|instagram|youtube|tiktok|pinterest|reddit|wikipedia|wikiwand|crunchbase|bloomberg|glassdoor|indeed|ziprecruiter|yelp|mapquest|tripadvisor|ballotpedia|govsalaries|transparentcalifornia|opencorporates|guidestar|charitynavigator|propublica|causeiq|idealist|zoominfo|rocketreach|starbridge|signalhire|apollo\.io|lusha|contactout|leadiq|hunter\.io|snov\.io|clearbit|aeroleads|datanyze|usphonebook|spokeo|radaris|whitepages|peoplefinder|nuwber|fastpeoplesearch|beenverified|truepeoplesearch|lead411|uplead|anymailfinder|emailhippo|voilanorbert|bizapedia|dnb\.com|manta|buzzfile|newsbreak|patch\.com|legistar|granicus|civicplus)\./i;

const STRIP_TLD = /\.(com|org|net|edu|gov|io|co|us|uk|ca|info|biz|ngo|charity)(\.[a-z]{2})?$/;
const rootOf = (h) => String(h || '').toLowerCase().replace(STRIP_TLD, '').replace(/[^a-z0-9]/g, '');
// n8n's Code sandbox does not expose the URL constructor. new URL() here
// returned '' for every result, so every host was discarded before scoring and
// all 15 fixture leads came back 'no host matched org name; considered none'
// even though the right domain was sitting at result #1. Parse with a regex.
const hostOf = (u) => { const m = String(u || '').match(/^[a-zA-Z][a-zA-Z0-9+.\-]*:\/\/([^\/?#:]+)/); return m ? m[1].replace(/^www\./i, '').toLowerCase() : ''; };

const acro = orgTok.map(t => t[0]).join('');
const best = { host: '', score: -1 };
const considered = [];

for (let i = 0; i < web.length; i++) {
  const host = hostOf(web[i].url);
  if (!host || NEVER.test(host + '.')) continue;

  const root = rootOf(host);
  let score = 0;
  let tokenHit = false;

  for (const t of orgTok) {
    if (t.length >= 4 && (root === t || root.startsWith(t) || root.endsWith(t))) { score += 40; tokenHit = true; break; }
    if (t.length >= 7 && root.includes(t)) { score += 35; tokenHit = true; break; }
    if (t.length === 3 && root === t) { score += 40; tokenHit = true; break; }
  }
  // Abbreviated hosts like wspmn.gov share no token with 'West St. Paul', so an
  // acronym match is the rescue. Require 3+ letters to avoid coincidence.
  if (!tokenHit && acro.length >= 3 && root === acro) { score += 35; tokenHit = true; }

  if (/\.gov$/.test(host)) score += 25;
  else if (/\.us$/.test(host)) score += 20;
  else if (/\.org$/.test(host)) score += 10;

  if (/official|home|welcome/i.test(web[i].title || '')) score += 5;
  score -= i;   // earlier results win ties

  considered.push(host + ':' + score);

  // Never accept a host with nothing to do with the org name. Without this the
  // first non-broker result wins by default, which is how v1 ended up writing
  // gates.org for the Gates Foundation and ag.org for an agri startup.
  if (!tokenHit) continue;

  if (score > best.score) { best.host = host; best.score = score; }
}

if (!best.host) {
  return { json: Object.assign({}, lead, { _domain: '', _domain_source: '', _domain_fail: 'no host matched org name; considered ' + (considered.join(', ') || 'none') }) };
}

return { json: Object.assign({}, lead, {
  _domain: best.host,
  _domain_source: 'firecrawl_search:' + best.host,
  _domain_fail: ''
}) };

// Could not establish the organisation's own website, so there is nowhere
// trustworthy to look. Retryable — the selector picks domain_not_found back up.
return { json: {
  provider_id: $json.provider_id,
  email_find_status: 'domain_not_found',
  email_evidence: String($json._domain_fail || 'no org domain resolved').slice(0, 400),
  email_found_at: new Date().toISOString()
}};

// Score the addresses visible in snippets from the organisation's OWN site.
// Never construct an address. Nothing surviving is a real answer: not_found.
const lead = $('Loop Over Leads').item.json;
const res = $json || {};
const now = new Date().toISOString();
const pid = lead.provider_id;
const person = String(lead._person || lead.name || '');
const orgTok = Array.isArray(lead._org_tokens) ? lead._org_tokens : [];

const web = (res.data && Array.isArray(res.data.web)) ? res.data.web
  : (Array.isArray(res.data) ? res.data : []);

// ---------- search failed: retryable, not a verdict ----------
if (res.error || (!res.data && !web.length)) {
  let msg = 'search returned no usable payload';
  if (res.error) { try { msg += ': ' + (typeof res.error === 'string' ? res.error : JSON.stringify(res.error)).slice(0, 300); } catch (e) {} }
  return { json: { provider_id: pid, email_find_status: 'search_error', email_evidence: msg, email_found_at: now }};
}

const EMAIL_RE = /[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}/g;
const OURS = /@(gofunditnow|deeplearningintelligence|gmail|googlemail|google)\./i;
const BAD_LOCAL = /^(noreply|no-reply|donotreply|do-not-reply|mailer-daemon|postmaster|example|email|yourname|your-email|name|username|user|test|sample|someone|firstname|lastname|first|last)$/i;
const NOT_A_TLD = /\.(png|jpe?g|gif|webp|svg|pdf|docx?|xlsx?|pptx?|zip|css|js|html?|aspx?|php)$/i;
const ROLE_LOCALS = new Set(['info','admin','administrator','contact','support','hello','office','mail','team','sales','billing','help','webmaster','enquiries','inquiries','general','donations','volunteer','assistance','press','media','pr','marketing','hr','careers','jobs','service','services','customerservice','reception','secretary','accounts','finance','legal','privacy','abuse','security','feedback','subscribe','newsletter','communications','development','grants','outreach','clerk','cityhall','planning','ecdev','econdev','economicdevelopment','citycouncil','council','communitydevelopment','commdev']);

const STRIP_TLD = /\.(com|org|net|edu|gov|io|co|us|uk|ca|info|biz|ngo|charity)(\.[a-z]{2})?$/;
const rootOf = (d) => String(d || '').toLowerCase().replace(STRIP_TLD, '').replace(/[^a-z0-9]/g, '');
// Same fix as Pick Org Domain: the Code sandbox has no URL constructor.
const hostOf = (u) => { const m = String(u || '').match(/^[a-zA-Z][a-zA-Z0-9+.\-]*:\/\/([^\/?#:]+)/); return m ? m[1].replace(/^www\./i, '').toLowerCase() : ''; };

// name parts for local-part matching
const parts = person.toLowerCase().replace(/[^a-z\s'\-]/g, ' ').split(/\s+/).filter(Boolean);
const first = parts[0] || '';
const last = parts.length > 1 ? parts[parts.length - 1] : '';
const lastBits = last.split(/[\-']/).filter(Boolean);

function localMatchesName(local) {
  const l = local.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (!first || !last) return false;
  const fi = first[0], li = last[0];
  const cands = new Set([first + last, fi + last, first + li, last + first, last + fi, fi + li + last, first, last]);
  for (const b of lastBits) { cands.add(fi + b); cands.add(first + b); cands.add(b); cands.add(fi + lastBits.join('')); }
  if (cands.has(l)) return true;
  // catches Councilmember.Fani-Gonzalez -> councilmemberfanigonzalez
  const lastJoined = lastBits.join('');
  if (lastJoined.length >= 5 && l.includes(lastJoined)) return true;
  if (last.length >= 5 && l.includes(last.replace(/[^a-z]/g, ''))) return true;
  return false;
}

const BACK_OFFICE = new Set(['hr','careers','jobs','accounts','finance','billing','legal','privacy','abuse','security','webmaster','postmaster','reception','secretary','subscribe','newsletter']);

const rejected = {};
const rej = (k) => { rejected[k] = (rejected[k] || 0) + 1; };
const seen = new Map();

for (let i = 0; i < web.length; i++) {
  const r = web[i] || {};
  const link = r.url || '';
  const host = hostOf(link);
  const blob = [r.title, r.description, r.snippet, r.markdown].filter(Boolean).join(' \n ');
  const found = blob.match(EMAIL_RE) || [];

  for (const raw of found) {
    const email = raw.replace(/[.,;:)\]]+$/, '');
    const lower = email.toLowerCase();
    const local = lower.split('@')[0] || '';
    const domain = lower.split('@')[1] || '';

    if (NOT_A_TLD.test(domain)) { rej('looks_like_filename'); continue; }
    if (OURS.test('@' + domain)) { rej('our_own_domain'); continue; }
    if (BAD_LOCAL.test(local)) { rej('placeholder_or_daemon'); continue; }
    if (domain.length < 4 || !domain.includes('.')) { rej('malformed_domain'); continue; }

    // The search was confined to the org's own site, but verify rather than
    // assume: the address must sit on the same root as the page it was found
    // on, or relate to the org name. A newspaper's customerservice@iniusa.org
    // quoted on an org page is exactly what this rejects.
    const sameRootAsPage = !!host && rootOf(host) === rootOf(domain);
    // Match at the edges of the domain, not anywhere inside it. 'Ottobock Care'
    // produced info@procarepando.com because 'care' sits inside 'procarepando'.
    // Same class of error as 'city' matching 'cityofpowdersprings'.
    const dr = rootOf(domain);
    const relatedToOrg = orgTok.some(t =>
      (t.length >= 4 && (dr === t || dr.startsWith(t) || dr.endsWith(t))) ||
      (t.length >= 7 && dr.includes(t)) ||
      (t.length === 3 && dr === t));
    if (!sameRootAsPage && !relatedToOrg) { rej('domain_not_the_org'); continue; }

    const isRole = ROLE_LOCALS.has(local) || /^(info|admin|contact|support|office|hello|press|media|assistance|enquir|inquir|councilmember)[._\-]/.test(local);
    const nameMatch = localMatchesName(local);
    if (!nameMatch && !isRole) { rej('local_part_matches_neither_person_nor_role'); continue; }

    let score = 0;
    if (nameMatch) score += 50;
    if (isRole && !nameMatch) score += 10;
    // Back-office mailboxes are the wrong fallback for these leads. Buckeye's
    // directory listed ecdev@, hr@ and pmo@ side by side and hr@ won on
    // ordering alone, for an economic-development lead.
    if (isRole && BACK_OFFICE.has(local)) score -= 30;
    if (sameRootAsPage) score += 25;
    if (relatedToOrg) score += 15;
    score -= Math.min(i, 9);

    const prev = seen.get(lower);
    if (!prev || score > prev.score) {
      seen.set(lower, {
        email: email, domain: domain, score: score, isRole: isRole, nameMatch: nameMatch,
        link: link, host: host,
        evidence: blob.replace(/\s+/g, ' ').slice(0, 400)
      });
    }
  }
}

const ranked = Array.from(seen.values()).sort((a, b) => b.score - a.score);
if (!ranked.length) {
  return { json: {
    provider_id: pid,
    email_find_status: 'not_found',
    email_evidence: 'searched ' + (lead._domain || 'org site') + ', no candidate survived: ' + (Object.keys(rejected).length ? JSON.stringify(rejected) : 'no addresses in snippets'),
    email_found_at: now
  }};
}

// A personal address always beats a role address, even on a lower score.
const pick = ranked.find(c => c.nameMatch) || ranked[0];

return { json: {
  provider_id: pid,
  email: pick.email,
  email_source: pick.nameMatch ? 'firecrawl_site_search' : 'firecrawl_role_account',
  email_confidence: pick.nameMatch ? 80 : 45,
  company_domain: pick.domain,
  company_domain_source: lead._domain_source || ('firecrawl_search:' + pick.host),
  email_source_url: pick.link,
  email_evidence: pick.evidence,
  email_find_status: pick.nameMatch ? 'found' : 'role_account',
  email_found_at: now
}};

// Both producer nodes run inside the batch loop, so $(...).all() returns only
// the LAST batch. Walk every run index for the true total — this is the bug
// that made the outreach run report 1 email sent when it had sent 25.
function collect(nodeName) {
  const rows = [];
  for (let r = 0; r < 2000; r++) {
    let batch;
    try { batch = $(nodeName).all(0, r); } catch (e) { break; }
    if (!batch || batch.length === 0) break;
    rows.push(...batch.map(i => i.json));
  }
  return rows;
}

let rows = [];
try { rows = rows.concat(collect('Extract Address')); } catch (e) {}
try { rows = rows.concat(collect('Mark No Org Domain')); } catch (e) {}

const tally = {};
for (const r of rows) {
  const k = r.email_find_status || 'unknown';
  tally[k] = (tally[k] || 0) + 1;
}

const addresses = rows
  .filter(r => r.email)
  .map(r => ({ provider_id: r.provider_id, email: r.email, status: r.email_find_status, source: r.email_source_url }));

return [{ json: {
  run_id: $execution.id,
  finished_at: new Date().toISOString(),
  searched_this_run: rows.length,
  by_status: tally,
  found_rate: rows.length ? Math.round(((tally.found || 0) / rows.length) * 100) + '%' : '0%',
  addresses: addresses
}}];

// The search we just paid for showed us a whole staff directory. The finder
// keeps the one address matching our lead and would otherwise bin the rest.
// Those discarded pairs are exactly what the pattern learner needs, so bank
// every one of them here. Costs nothing - the request is already made.
// Runs once per batch, not per item: the batch size is 1, so .first() is this
// lead. 'run once for each item' mode cannot be used here because this node
// emits MANY rows from ONE input item - that mode requires exactly one object
// back and rejects an array with "a 'json' property isn't an object".
const lead = $('Loop Over Leads').first().json;
const res = $('Firecrawl: Search Org Site').first().json || {};
const now = new Date().toISOString();
const domain = String(lead._domain || '').toLowerCase();

const web = (res.data && Array.isArray(res.data.web)) ? res.data.web
  : (Array.isArray(res.data) ? res.data : []);
if (!web.length || !domain) return [];

const EMAIL_RE = /[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}/g;
const NAME_RE = /\b([A-Z][a-z]{1,15})\s+(?:[A-Z]\.?\s+)?([A-Z][a-zA-Z'\-]{1,20})\b/g;
const ROLE_LOCALS = new Set(['info','admin','administrator','contact','support','hello','office','mail','team','sales','billing','help','webmaster','postmaster','enquiries','inquiries','general','donations','volunteer','assistance','press','media','marketing','hr','careers','jobs','service','services','reception','secretary','accounts','finance','legal','privacy','abuse','security','feedback','subscribe','newsletter','communications','development','grants','outreach','clerk','cityhall','planning','ecdev','econdev','economicdevelopment','citycouncil','council','commdev','records','permits','utilities','court','library','museum','parks','police','fire','water','sewer']);
const NOT_A_NAME = new Set(['staff','directory','contact','city','town','county','department','office','email','phone','main','street','road','avenue','suite','public','works','human','resources','economic','community','development','police','fire','parks','recreation','skip','content','read','more','view','all','site','map','privacy','policy','terms','use','home','page','search','menu','close','open','click','here','learn','copyright','rights','reserved','government','services','business','residents','quick','links','records','division','board','committee','center','centre','foundation','church','temple','school','university','college','hospital','clinic','district','authority','commission','association','society','institute','trust','fund','group','our','people','meet','about']);

const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
function formatsFor(first, last) {
  const f = first[0], l = last[0];
  return [f + last, first + '.' + last, first + last, f + '.' + last, first + '_' + last,
    first + '-' + last, first + l, last + f, last + '.' + first, last + first, first, last, f + l];
}

const emails = new Map();
const names = new Map();

for (const r of web) {
  const url = r.url || '';
  const text = [r.title, r.description, r.snippet, r.markdown].filter(Boolean).join(' \n ');
  if (!text) continue;

  for (const raw of (text.match(EMAIL_RE) || [])) {
    const em = raw.replace(/[.,;:)\]]+$/, '');
    const lower = em.toLowerCase();
    const local = lower.split('@')[0] || '';
    const d = lower.split('@')[1] || '';
    if (d !== domain && !d.endsWith('.' + domain)) continue;
    if (ROLE_LOCALS.has(local)) continue;
    if (!emails.has(lower)) emails.set(lower, { email: em, local: local, url: url });
  }

  let m; NAME_RE.lastIndex = 0;
  while ((m = NAME_RE.exec(text)) !== null) {
    const first = m[1].toLowerCase(), last = m[2].toLowerCase();
    if (NOT_A_NAME.has(first) || NOT_A_NAME.has(last)) continue;
    if (first.length < 2 || last.length < 2) continue;
    names.set(first + ' ' + last, { first: first, last: last });
  }
}

// Only bank a pair when the address can actually be built from the name. An
// address we cannot attribute teaches us nothing about the format.
const rows = [];
for (const [lower, e] of emails) {
  const ln = norm(e.local);
  let who = '';
  for (const [key, n] of names) {
    const built = formatsFor(n.first, n.last);
    if (built.indexOf(e.local.toLowerCase()) !== -1 || built.some(b => norm(b) === ln)) { who = key; break; }
  }
  if (!who) continue;
  rows.push({ json: {
    pair_key: domain + '|' + lower,
    domain: domain,
    person_name: who,
    email: e.email,
    local_part: e.local,
    source_url: e.url,
    seen_at: now,
    found_by: 'email_finder'
  }});
}

return rows;
